#define LORA_RX 16
#define LORA_TX 17
#define M0 18
#define M1 19
#define AUX 4

HardwareSerial LoRa(2);

void setup() {
  Serial.begin(115200);

  pinMode(M0, OUTPUT);
  pinMode(M1, OUTPUT);
  pinMode(AUX, INPUT);

  digitalWrite(M0, HIGH);
  digitalWrite(M1, HIGH);

  LoRa.begin(9600, SERIAL_8N1, LORA_RX, LORA_TX);

  delay(1000);

  Serial.println("ESP32 LORA MODULE TEST");
  Serial.println("----------------------");
  Serial.println("UART INITIALIZED");
  Serial.println("Normal mode selected");
}

void loop() {
  Serial.println("Sending test data to LoRa...");
  LoRa.println("HELLO LORA MODULE");

  delay(1000);

  Serial.print("AUX STATUS: ");
  Serial.println(digitalRead(AUX));

  if (LoRa.available()) {
    Serial.println("LoRa UART DATA RECEIVED:");

    while (LoRa.available()) {
      Serial.write(LoRa.read());
    }
  }

  Serial.println("----------------------");
  delay(2000);
}
